# 6. The window's state: cadence, failures, the comparison with the latest good reading, one reading at a time.
class Clock:
    def __init__(self): self.now = 5000.0
    def __call__(self): return self.now
class Reader:
    def __init__(self, *results): self.results, self.calls = list(results), 0
    def __call__(self):
        self.calls += 1
        result = self.results.pop(0)
        if isinstance(result, BaseException):
            raise result
        return result
