class Window:
    def __init__(self, page, at): self.page, self.at, self.log = page, at, []
    def sida(self): self.log.append('sida'); return self.page
    def read_at(self): self.log.append('read_at'); return self.at
    def kanske_las(self): self.log.append('kanske_las'); return False
    def las_om(self): self.log.append('las_om'); return False
