def verify(candidate):
    from runtime.profile import sandbox_command, environment
    p = subprocess.run(sandbox_command(Path(candidate), ['/opt/homebrew/bin/python3.12', '-I', '-B', '-c', WINDOW]),
                       env=environment(), capture_output=True, text=True, timeout=900)
    if p.returncode:
        return {'passed': False, 'reason': 'Aquarium window host contract failed', 'stderr': p.stderr[-6000:]}
    try:
        result = json.loads(p.stdout)
    except ValueError:
        return {'passed': False, 'reason': 'Missing host acceptance result for the window'}
    if result.get('passed') is not True:
        return {'passed': False, 'reason': 'Aquarium window host contract did not pass'}
    return {'passed': True, 'checks': result.get('checks', []),
            'scope': 'The window and its comparison on synthetic readings only; the real window on 127.0.0.1 in a browser is verified separately by the host'}
